WHERE is_deleted = 0
 AND project_id = #{projectId}
 AND effective_from = #{period}
 AND batch_id = #{batchId}
 AND dq_status = #{dqStatus}

SELECT DISTINCT project_id AS projectId, department_id AS departmentId FROM ecos_dw.ecos_biz_project_attribution WHERE is_deleted = 0 AND is_active = 1 AND dq_status IN ('PASSED', 'PUBLISHED') AND project_id IN
